from pathlib import Path


BASE_DIR = Path("/app")
INPUT_PATH = BASE_DIR / "src" / "INPUT.DAT"
DATA_DIR = BASE_DIR / "data"

ACCOUNT_RECORD_SIZE = 34
BOOK_RECORD_SIZE = 28
TRANSACTION_RECORD_SIZE = 22


def first_record(data: bytes, size: int) -> bytes:
    return data[:size].ljust(size, b"\x00")


def numeric_input_bytes(field: bytes) -> bytes:
    return bytes(byte if byte >= ord("0") else ord("0") for byte in field)


def numeric_input_value(field: bytes) -> int:
    value = 0
    for byte in field:
        value = value * 10 + (byte - ord("0") if byte >= ord("0") else 0)
    return value


def format_account_balance(value: int) -> bytes:
    return f"{value % 10_000_000_000:010d}".encode("ascii")


def replace_records(path: Path, record_size: int, update) -> None:
    original = path.read_bytes()
    output = bytearray(original)
    for offset in range(0, len(original), record_size):
        record = bytearray(first_record(original[offset : offset + record_size], record_size))
        if update(record):
            if offset + record_size <= len(output):
                output[offset : offset + record_size] = record
            else:
                output[offset:] = record
    path.write_bytes(output)


def main() -> None:
    input_data = INPUT_PATH.read_bytes()
    if not input_data:
        print("Error: Input file is empty")
        return

    input_record = first_record(input_data, 22)
    buyer_id = input_record[0:4]
    seller_id = input_record[4:8]
    book_id = input_record[8:12]
    input_amount = input_record[12:22]
    transaction_amount = numeric_input_bytes(input_amount)
    amount = numeric_input_value(input_amount)

    buyer_found = False
    seller_found = False
    book_found = False
    valid_owner = False

    accounts_data = (DATA_DIR / "ACCOUNTS.DAT").read_bytes()
    for offset in range(0, len(accounts_data), ACCOUNT_RECORD_SIZE):
        record = first_record(accounts_data[offset : offset + ACCOUNT_RECORD_SIZE], ACCOUNT_RECORD_SIZE)
        account_id = record[0:4]
        if account_id == buyer_id:
            buyer_found = True
        if account_id == seller_id:
            seller_found = True

    books_data = (DATA_DIR / "BOOKS.DAT").read_bytes()
    for offset in range(0, len(books_data), BOOK_RECORD_SIZE):
        record = first_record(books_data[offset : offset + BOOK_RECORD_SIZE], BOOK_RECORD_SIZE)
        if record[0:4] == book_id:
            book_found = True
            if record[24:28] == seller_id:
                valid_owner = True

    print(" ")

    if not (buyer_found and seller_found and book_found and valid_owner):
        print("Transaction failed due to validation errors")
        return

    def update_account(record: bytearray) -> bool:
        account_id = bytes(record[0:4])
        if account_id != buyer_id and account_id != seller_id:
            return False

        balance = numeric_input_value(bytes(record[24:34]))
        if account_id == buyer_id:
            balance = abs(balance - amount)
            record[24:34] = format_account_balance(balance)
        if account_id == seller_id:
            balance = (balance + amount) % 10_000_000_000
            record[24:34] = format_account_balance(balance)
        return True

    replace_records(DATA_DIR / "ACCOUNTS.DAT", ACCOUNT_RECORD_SIZE, update_account)

    def update_book(record: bytearray) -> bool:
        if bytes(record[0:4]) != book_id:
            return False
        record[24:28] = buyer_id
        return True

    replace_records(DATA_DIR / "BOOKS.DAT", BOOK_RECORD_SIZE, update_book)

    with (DATA_DIR / "TRANSACTIONS.DAT").open("ab") as transactions_file:
        transactions_file.write(book_id)
        transactions_file.write(transaction_amount)
        transactions_file.write(seller_id)
        transactions_file.write(buyer_id)

    print("Transaction completed successfully")


if __name__ == "__main__":
    main()

